// nomore2percent service worker
// Hand-written (not generated by a bundler plugin) so it works cleanly with
// Next.js + Turbopack, which next-pwa/Workbox's Webpack-based generation
// does not reliably support.
//
// Strategy:
// - Never touch /api/* or /admin/* — always fresh from the network. These are
//   dynamic, sometimes authenticated, and must never be served stale.
// - Static assets (icons, manifest, offline page) — cache-first, since they
//   rarely change and speed matters more than freshness.
// - Page navigations — network-first, falling back to a cached copy of the
//   same page if offline, and finally to the offline fallback page.

const CACHE_NAME = 'n2p-shell-v1';
const PRECACHE_URLS = [
  '/offline.html',
  '/manifest.webmanifest',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => cache.addAll(PRECACHE_URLS))
  );
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys.filter((k) => k !== CACHE_NAME).map((k) => caches.delete(k)))
    )
  );
  self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);

  // Only handle same-origin GET requests — everything else passes through untouched.
  if (request.method !== 'GET' || url.origin !== self.location.origin) return;

  // Never cache API routes or the admin panel — always hit the network.
  if (url.pathname.startsWith('/api/') || url.pathname.startsWith('/admin')) {
    return;
  }

  // Page navigations: network-first, cache the successful response for offline
  // reuse, fall back to cache then to the offline page if the network fails.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone();
          caches.open(CACHE_NAME).then((cache) => cache.put(request, copy));
          return response;
        })
        .catch(() =>
          caches.match(request).then((cached) => cached || caches.match('/offline.html'))
        )
    );
    return;
  }

  // Static assets (icons, images, fonts, build chunks): cache-first for speed.
  if (
    url.pathname.startsWith('/icons/') ||
    url.pathname.startsWith('/_next/static/') ||
    /\.(png|jpg|jpeg|svg|webp|ico|woff2?)$/.test(url.pathname)
  ) {
    event.respondWith(
      caches.match(request).then(
        (cached) =>
          cached ||
          fetch(request).then((response) => {
            const copy = response.clone();
            caches.open(CACHE_NAME).then((cache) => cache.put(request, copy));
            return response;
          })
      )
    );
  }
});
